import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { VitePWA } from 'vite-plugin-pwa';

// Where the app is served from. '/' for local use and most hosts; GitHub Pages serves a
// project site from '/<repo>/', so that build sets GHARMAP_BASE=/GharMap/ (see `npm run build:pages`).
const base = process.env.GHARMAP_BASE ?? '/';

export default defineConfig({
  base,
  plugins: [
    react(),
    // Makes the built app installable ("Add to Home Screen") and usable offline.
    // The service worker is only generated by `npm run build`; dev and e2e run without one.
    VitePWA({
      registerType: 'autoUpdate',
      includeAssets: ['icon.svg', 'apple-touch-icon.png'],
      manifest: {
        name: 'GharMap',
        short_name: 'GharMap',
        description: 'A map of your home that answers "where is it?"',
        start_url: base,
        scope: base,
        display: 'standalone',
        background_color: '#f4f5f7',
        theme_color: '#0F6E66',
        icons: [
          { src: 'icon-192.png', sizes: '192x192', type: 'image/png' },
          { src: 'icon-512.png', sizes: '512x512', type: 'image/png' },
          { src: 'icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
        ],
      },
      // Every route is the same single page, so an offline deep link still opens the app.
      workbox: { navigateFallback: `${base}index.html`, globPatterns: ['**/*.{js,css,html,svg,png}'] },
    }),
  ],
  // host: true lets a phone on the same Wi-Fi open the dev server.
  server: { host: true, port: 5173 },
});
